import Image from "next/image";
import Link from "next/link";
import { api } from "@/lib/api/client";
import type { Project } from "@/types/api";
export function ProjectsList({projects}:{projects:Project[]}){if(!projects.length)return <p className="py-8 text-stone-600">لا توجد مشاريع منشورة حالياً.</p>;return <div className="grid gap-10 md:grid-cols-2">{projects.map((project,i)=>{const image=api.mediaUrl(project.image);return <article key={project.id} className={i%3===0?"md:col-span-2":""}><Link href={`/projects/${project.id}`} className="group block">{image?<div className="relative aspect-[16/9] overflow-hidden bg-[#d7d2c8]"><Image src={image} alt={project.title} fill className="object-cover transition duration-700 group-hover:scale-[1.03]" sizes="(max-width: 768px) 100vw, 66vw" /></div>:<div className="flex aspect-[16/9] items-end bg-[#d7d2c8] p-6 text-5xl text-[#52604d]">{String(i+1).padStart(2,"0")}</div>}<div className="mt-4 flex items-baseline justify-between gap-4"><h3 className="text-3xl font-bold">{project.title}</h3><span className="text-sm">عرض المشروع ←</span></div><p className="mt-2 max-w-xl text-black/65">{project.description}</p></Link></article>})}</div>}
